# Links + labels re-used from the buried Guardianship crisis-hold cards, which
# were built from official state sources. AK/IL/NY/MI links returned 000 on the
# Nov 14, 2026 sweep and are omitted here; AR/GA have no buried link.
DROP_LINKS = {"alaska", "illinois", "new-york", "michigan"}

def main():
    buried = json.load(open("/tmp/buried.json"))
    states = {}
    for slug in sorted(STATE_NAMES):
        f = FIELDS[slug]
        links = [(u, a) for (u, a) in buried[slug]["links"]
                 if "988lifeline" not in u]
        link, label = (links[0] if links and slug not in DROP_LINKS else (None, None))
        states[slug] = {
            "state": STATE_NAMES[slug], "slug": slug,
            "statute": f["statute"], "named": f["named"],
            "hold": f["hold"], "hold_extra": f["hold_extra"],
            "initiators": f["initiators"], "hearing": f["hearing"],
            "link": link, "link_label": label,
        }
    assert len(states) == 50
    assert all(states[s]["statute"] and states[s]["hold"] and states[s]["initiators"]
               for s in states)
    json.dump({"states": states},
              open("/home/hatch/workspace/goals/50-state-legal-resource-website/site/hidden_files/topic-research/mental-health-crisis-holds/all-states.json", "w"),
              indent=1, ensure_ascii=False)
    print("wrote 50 states;",
          sum(1 for s in states.values() if s["link"]), "with statute link,",
          sum(1 for s in states.values() if s["hearing"]), "with hearing deadline,",
          sum(1 for s in states.values() if s["named"]), "with named law")

if __name__ == "__main__":
    main()
